#!/usr/bin/env python3
"""Strict verifier for case 01."""

from __future__ import annotations

import json
import hashlib
import math
import re
import sys
from decimal import Decimal
from pathlib import Path
from typing import Any


ROOT = Path(__file__).resolve().parents[1]
INPUT = ROOT / "data.json"
OUTPUT = ROOT / "result.json"
MONEY_RE = re.compile(r"^-?(?:0|[1-9]\d*)\.\d{2}$")
INPUT_SHA256 = "33180ad90521b06c69a44b72987be76d0365a7fc330f047ab4c1b84ac4d86097"


class DuplicateKeyError(ValueError):
    pass


def no_duplicate_object(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
    result: dict[str, Any] = {}
    for key, value in pairs:
        if key in result:
            raise DuplicateKeyError(f"duplicate object key: {key!r}")
        result[key] = value
    return result


def load_json(path: Path) -> Any:
    with path.open("r", encoding="utf-8") as handle:
        return json.load(handle, object_pairs_hook=no_duplicate_object)


def canonical(value: Any) -> str:
    return json.dumps(
        value,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
        allow_nan=False,
    )


def fail(message: str) -> None:
    print(f"FAIL: {message}", file=sys.stderr)
    raise SystemExit(1)


def main() -> None:
    if not INPUT.is_file():
        fail("benchmark input is missing")
    if hashlib.sha256(INPUT.read_bytes()).hexdigest() != INPUT_SHA256:
        fail("data.json was modified")
    try:
        source = load_json(INPUT)
    except Exception as exc:  # fixture corruption is a benchmark failure
        fail(f"cannot read benchmark input: {exc}")

    if not isinstance(source, dict) or not isinstance(source.get("items"), list):
        fail("benchmark input has an invalid schema")

    expected_items: list[Any] = []
    expected_sum = Decimal("0")
    for item in source["items"]:
        if not isinstance(item, dict) or "price" not in item:
            continue
        price = item["price"]
        if isinstance(price, bool) or not isinstance(price, (int, float)):
            continue
        if isinstance(price, float) and not math.isfinite(price):
            continue
        if price > 100:
            expected_items.append(item)
            expected_sum += Decimal(str(price))

    if not OUTPUT.is_file():
        fail("result.json does not exist")
    if OUTPUT.stat().st_size > 64 * 1024 * 1024:
        fail("result.json is unexpectedly large")

    try:
        result = load_json(OUTPUT)
    except Exception as exc:
        fail(f"result.json is not valid JSON: {exc}")

    if not isinstance(result, dict):
        fail("result.json must contain an object")
    required_keys = {"items", "matching_count", "price_sum"}
    if set(result) != required_keys:
        fail("result.json must contain exactly the required three fields")

    if not isinstance(result["items"], list):
        fail("items must be an array")
    if canonical(result["items"]) != canonical(expected_items):
        fail("items does not exactly match the required filtered sequence")

    count = result["matching_count"]
    if isinstance(count, bool) or not isinstance(count, int):
        fail("matching_count must be an integer")
    if count != len(expected_items):
        fail("matching_count is incorrect")

    price_sum = result["price_sum"]
    if not isinstance(price_sum, str) or MONEY_RE.fullmatch(price_sum) is None:
        fail("price_sum must be a two-decimal string")
    if price_sum != f"{expected_sum:.2f}":
        fail("price_sum is incorrect")

    print("PASS: result.json satisfies all requirements")


if __name__ == "__main__":
    main()
